"""web_login.py — Stitch glass login in a native WebView2 window (pywebview),
shown BEFORE the Flet app when no session exists. The HTML form is bridged to
auth_supabase; on success the session is cached so the Flet app boots straight in.

Returns from run_login():
  {"user": <dict>, "theme": "dark"|"light"}  on successful sign-in
  None                                         user closed the window w/o signing in
  {"unavailable": True}                        pywebview not installed (caller should
                                               fall back to the in-app Flet gate)

Windows deps:  pip install pywebview pythonnet   (Edge WebView2 runtime backend)
"""
import base64
import os
import threading

import auth_supabase as auth

_HTML_B64 = ""


def _version():
    try:
        here = os.path.dirname(os.path.abspath(__file__))
        with open(os.path.join(here, "VERSION"), "r", encoding="utf-8") as f:
            return f.read().strip()
    except Exception:
        return ""


def _html():
    html = base64.b64decode(_HTML_B64).decode("utf-8")
    ver = _version()
    if ver:
        # inject the live version before the main script reads it
        html = html.replace(
            '<script>const VER=',
            '<script>window.__qaVersion="' + ver + '";</script>\n<script>const VER=',
            1)
    return html


class _Api:
    def __init__(self):
        self.result = None
        self.window = None

    def submit(self, p):
        try:
            p = p or {}
            action = p.get("action"); email = p.get("email"); pw = p.get("password")
            name = p.get("name"); theme = p.get("theme")
            if action == "signup":
                ok, msg, user = auth.sign_up(email, pw, name=name or None)
            else:
                ok, msg, user = auth.sign_in(email, pw)
            if user:
                self.result = {"user": user, "theme": theme}
                # Primary close path is JS calling window.close() (see __qaResult),
                # which pywebview handles ON THE UI THREAD via WindowCloseRequested —
                # the safe way to tear down WebView2. Destroying from a Python
                # background thread here is what deadlocked and left the process
                # alive. We keep a guarded Timer destroy only as a late fallback in
                # case window.close() is a no-op on an older backend.
                def _close():
                    try:
                        if self.window:
                            self.window.destroy()
                    except Exception:
                        pass
                try:
                    threading.Timer(0.8, _close).start()
                except Exception:
                    pass
                return {"ok": True, "close": True}
            return {"ok": bool(ok), "message": msg, "kind": "ok" if ok else "err",
                    "action": action}
        except Exception as ex:
            return {"ok": False, "message": "Something went wrong: %s" % ex, "kind": "err"}

    def forgot(self, p):
        try:
            ok, msg = auth.request_password_reset((p or {}).get("email"))
            return {"ok": bool(ok), "message": msg, "kind": "ok" if ok else "err"}
        except Exception as ex:
            return {"ok": False, "message": str(ex), "kind": "err"}


def run_login(width=1120, height=760, title="QA Studio"):
    try:
        import webview
    except Exception:
        return {"unavailable": True}
    # Give this launch its own WebView2 user-data folder (and clear leftovers from
    # previous runs). WebView2 otherwise reuses a profile dir that stays locked by
    # leaked msedgewebview2.exe helper processes — which is what made the app wedge
    # from the 3rd launch on. A fresh per-run dir avoids the lock; the parent's Job
    # Object (see main._run_web_login_subprocess) kills any leftover helpers.
    _storage = None
    try:
        import tempfile as _tf, shutil as _sh, glob as _gl
        _root = _tf.gettempdir()
        for _old in _gl.glob(os.path.join(_root, "qa_wv2_*")):
            try:
                _sh.rmtree(_old, ignore_errors=True)
            except Exception:
                pass
        _storage = _tf.mkdtemp(prefix="qa_wv2_")
    except Exception:
        _storage = None
    api = _Api()
    try:
        import logging
        logging.getLogger("pywebview").setLevel(logging.CRITICAL)
    except Exception:
        pass
    # DPI awareness + centre on the primary screen.
    #
    # Ask for PER-MONITOR-V2 awareness (not just system-DPI): under plain system
    # awareness, dragging the WebView2 window onto a monitor with a different scale
    # forces a DPI change the backend can't ride out, which freezes/crashes it
    # mid-drag. Per-monitor-v2 lets WebView2 rescale cleanly. Fall back on old OS.
    #
    # Centring: pywebview places the window in *logical* (DPI-scaled) pixels, but
    # GetSystemMetrics returns *physical* pixels once DPI-aware. Divide by the
    # scale factor first, else on a scaled display the window lands pushed to the
    # right/low (the off-centre bug).
    _x = _y = None
    try:
        import ctypes
        _set = False
        try:
            # PROCESS_PER_MONITOR_DPI_AWARE_V2 = -4 (Win10 1703+)
            ctypes.windll.user32.SetProcessDpiAwarenessContext(ctypes.c_void_p(-4))
            _set = True
        except Exception:
            pass
        if not _set:
            try:
                ctypes.windll.shcore.SetProcessDpiAwareness(2)  # per-monitor
                _set = True
            except Exception:
                pass
        if not _set:
            try:
                ctypes.windll.shcore.SetProcessDpiAwareness(1)  # system
            except Exception:
                pass
        _u = ctypes.windll.user32
        _sw, _sh = _u.GetSystemMetrics(0), _u.GetSystemMetrics(1)
        _scale = 1.0
        try:
            _scale = (_u.GetDpiForSystem() or 96) / 96.0
        except Exception:
            try:
                _dc = _u.GetDC(0)
                _scale = (ctypes.windll.gdi32.GetDeviceCaps(_dc, 88) or 96) / 96.0
                _u.ReleaseDC(0, _dc)
            except Exception:
                _scale = 1.0
        if _scale <= 0:
            _scale = 1.0
        _lw, _lh = _sw / _scale, _sh / _scale
        _x = int(max(0, (_lw - int(width)) / 2))
        _y = int(max(0, (_lh - int(height)) / 2))
    except Exception:
        _x = _y = None

    # window + taskbar icon (else it shows the generic python.exe icon)
    _icon = None
    try:
        _here = os.path.dirname(os.path.abspath(__file__))
        for _n in ("app.ico", "app.png"):
            _p = os.path.join(_here, _n)
            if os.path.exists(_p):
                _icon = _p
                break
    except Exception:
        _icon = None

    _cw = dict(title=title, html=_html(), js_api=api,
               width=int(width), height=int(height), min_size=(940, 620))
    if _x is not None:
        _cw["x"], _cw["y"] = _x, _y
    try:
        api.window = webview.create_window(**_cw)
    except Exception:
        # some backends reject x/y — retry centred-less
        _cw.pop("x", None); _cw.pop("y", None)
        try:
            api.window = webview.create_window(**_cw)
        except Exception:
            return {"unavailable": True}

    def _start():
        # Prefer an isolated per-run profile (private_mode + storage_path) so no
        # locked/shared WebView2 profile can wedge later launches. icon= and these
        # kwargs are newer pywebview; fall back gracefully on older builds.
        _kw = dict(gui="edgechromium", private_mode=True)
        if _storage:
            _kw["storage_path"] = _storage
        if _icon:
            _kw["icon"] = _icon
        try:
            webview.start(**_kw)
            return
        except TypeError:
            pass
        # drop the newest kwargs one tier at a time
        try:
            webview.start(gui="edgechromium", private_mode=True)
            return
        except TypeError:
            pass
        webview.start(gui="edgechromium")

    try:
        _start()
    except Exception:
        try:
            webview.start()
        except Exception:
            return {"unavailable": True}
    finally:
        # Best-effort remove this run's profile dir (pywebview also rmtrees it on
        # close when private_mode is on; this covers the crash/abort paths).
        try:
            if _storage:
                import shutil as _sh2
                _sh2.rmtree(_storage, ignore_errors=True)
        except Exception:
            pass
    return api.result
